mapper.select:
SELECT A.SEQNO SEQNO, A.CREDIT_MST_ID creditMstId, A.CUSTOMER_ID customerId, A.TERM TERM, A.PFLSH PFLSH, A.CREDIT_AMT/100000000 creditAmt, A.VDATE VDATE, A.MDATE MDATE, A.REMARK, A.HAP_CREDIT_AMT as hapCreditAmt, C.CUSTOMER_NAME as customerName, D.INSITITUTE_CODE as insitituteCode FROM CREDIT_LINES A INNER JOIN CREDIT_MST_INFO B on A.CREDIT_MST_ID=B.SEQNO and B.CREDIT_INFO_TYPE in ('01') left join MST_CUSTOMER_INFO C on A.CUSTOMER_ID=C.CUSTOMER_ID left join MST_CUSTOMER_INFO_ADD D on A.CUSTOMER_ID=D.CUSTOMER_ID
A.CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}
AND A.PFLSH LIKE concat_ws('','%',#{pflsh},'%')
AND DATE_FORMAT(A.VDATE,'%Y-%m-%d') > = #{vdate,jdbcType=DATE}
AND DATE_FORMAT(A.VDATE,'%Y-%m-%d') < = #{mdate,jdbcType=DATE}

       SELECT
	 	count(1)
	 FROM 
	 	CREDIT_LINES A
        where CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}


      and DATE_FORMAT(VDATE,'%Y-%m-%d')<= #{vmdate, jdbcType=VARCHAR}
       and DATE_FORMAT(MDATE,'%Y-%m-%d')>=#{vmdate, jdbcType=VARCHAR} 


			 and  SEQNO <> #{seqno}

       SELECT
	 	count(1)
	 FROM 
	 	CREDIT_LINES A
        where CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}


      and DATE_FORMAT(VDATE,'%Y-%m-%d')>= #{vdate, jdbcType=VARCHAR}
       and DATE_FORMAT(MDATE,'%Y-%m-%d')<=#{mdate, jdbcType=VARCHAR} 


			 and  SEQNO <> #{seqno}

		SELECT count(1)
		FROM CREDIT_LINES A
		where CUSTOMER_ID = #{customerId,jdbcType=VARCHAR}

      and DATE_FORMAT(VDATE,'%Y-%m-%d')>= #{vdate, jdbcType=VARCHAR}
       and DATE_FORMAT(MDATE,'%Y-%m-%d')<=#{mdate, jdbcType=VARCHAR}

        and A.PFLSH = #{pflsh,jdbcType=VARCHAR}
		and  A.Hap_Credit_Amt>0
